{
  "implementation": "def solve(case):
    segments = case['segments']
    budget = case['budget']
    n = len(segments)
    alloc = [seg['minimum'] for seg in segments]
    remaining = budget - sum(alloc)
    capacities = [seg['capacity'] for seg in segments]
    importances = [seg['importance'] for seg in segments]
    while remaining > 0:
        best_idx = -1
        best_ratio = -1.0
        for i in range(n):
            if alloc[i] < capacities[i]:
                ratio = importances[i] / (alloc[i] + 1.0)
                if ratio > best_ratio or (ratio == best_ratio and (best_idx == -1 or i < best_idx)):
                    best_ratio = ratio
                    best_idx = i
        if best_idx == -1:
            break
        alloc[best_idx] += 1
        remaining -= 1
    by_name = {segments[i]['name']: alloc[i] for i in range(n)}
    total = sum(alloc)
    return {"allocations": alloc, "by_name": by_name, "total": total}"
}
